// ─── File: PeeringDemo.java ───
package com.bank.peer;

import java.util.logging.*;

public class PeeringDemo {
    private static final Logger log = Logger.getLogger("Peering");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        // Broken: return route on VPC B is missing.
        PeeringConfig broken = new PeeringConfig();
        broken.cidrA = "10.0.0.0/16";
        broken.cidrB = "10.1.0.0/16";       // non-overlapping — good
        broken.routeAtoB = true;
        broken.routeBtoA = false;            // <-- missing return route
        broken.sgAllows = true;
        broken.naclAllowsBothWays = true;

        PeeringDiagnostic diag = new PeeringDiagnostic();
        log.warning(() -> "Broken case: " + diag.diagnose(broken));

        PeeringConfig fixed = new PeeringConfig();
        fixed.cidrA = "10.0.0.0/16"; fixed.cidrB = "10.1.0.0/16";
        fixed.routeAtoB = fixed.routeBtoA = true;
        fixed.sgAllows = fixed.naclAllowsBothWays = true;
        log.info(() -> "Fixed case:  " + diag.diagnose(fixed));
    }
}

// ─── Would be in PeeringConfig.java ───
class PeeringConfig {
    String cidrA, cidrB;
    boolean routeAtoB, routeBtoA, sgAllows, naclAllowsBothWays;
}

// ─── Would be in PeeringDiagnostic.java ───
class PeeringDiagnostic {
    String diagnose(PeeringConfig c) {
        if (overlap(c.cidrA, c.cidrB))
            return "CIDRs overlap — design error, must re-address one VPC (peering impossible)";
        if (!c.routeAtoB) return "Missing route A→B: add B's CIDR → pcx on VPC A";
        if (!c.routeBtoA) return "Missing RETURN route B→A: add A's CIDR → pcx on VPC B";
        if (!c.sgAllows)  return "Security Group on target does not allow source CIDR";
        if (!c.naclAllowsBothWays) return "NACL must allow traffic both directions on both subnets";
        return "Peering healthy — instances can reach each other over private IP";
    }
    private boolean overlap(String a, String b) {
        // demo: overlap if same first octet block and same prefix base
        return a.split("\\.")[0].equals(b.split("\\.")[0])
            && a.split("\\.")[1].equals(b.split("\\.")[1]);
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n", r.getMillis(), r.getLevel(), r.getMessage());
    }
}
